                if abs(dx) + abs(dy) == 1 and 0 <= x+dx < self.width and 0 <= y+dy < self.height:
                    neighbors.append((x+dx, y+dy))
        return neighbors


class Node:
    def __init__(self, state: int, cost: float = 0.0):
        self.state = state
        self.cost = cost

    def __lt__(self, other: 'Node') -> bool:
        return self.cost < other.cost


def heuristic(node: Node) -> float:
    # Manhattan distance
    x, y = divmod(node.state, 3)
    goal_x, _ = divmod(7, 3)
    return abs(x - goal_x) + abs(y)


